178	  Future<String> sdkLocation(SdkType sdk) async {
179	    assert(sdk != null);
180	    final RunResult runResult = await _processUtils.run(
181	      <String>['xcrun', '--sdk', getNameForSdk(sdk), '--show-sdk-path'],
182	    );
183	    if (runResult.exitCode != 0) {
184	      throwToolExit('Could not find SDK location: ${runResult.stderr}');
185	    }
186	    return runResult.stdout.trim();
187	  }
