135	    final List<SimDevice> devices = <SimDevice>[];
136	
137	    final Map<String, dynamic> devicesSection = await _list(SimControlListSection.devices);
138	
139	    for (final String deviceCategory in devicesSection.keys) {
140	      final Object devicesData = devicesSection[deviceCategory];
141	      if (devicesData != null && devicesData is List<dynamic>) {
